-- Fact-only reference dataset. Every populated value is traceable to the source
-- attached to the row. Unknown facts remain NULL; no gameplay ratings belong here.

create table if not exists public.data_sources (
  id bigint generated by default as identity primary key,
  source_key text not null unique,
  publisher text not null,
  title text not null,
  url text not null,
  season integer,
  retrieved_on date not null
);

create table if not exists public.f1_team_facts (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  short_name text not null,
  official_full_name text not null,
  legal_name text,
  base_city text,
  base_country text,
  team_chief text,
  technical_chief text,
  chassis text,
  power_unit text,
  first_team_entry integer,
  source_key text not null references public.data_sources(source_key),
  verified_on date not null
);

create table if not exists public.people (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  first_name text not null,
  last_name text not null,
  display_name text not null,
  date_of_birth date,
  racing_nationality text,
  place_of_birth text,
  person_type text not null check (person_type in ('driver','staff','driver_and_staff')),
  f1_debut_season integer,
  source_key text not null references public.data_sources(source_key),
  verified_on date not null
);

create table if not exists public.series_entries (
  id bigint generated by default as identity primary key,
  person_id bigint not null references public.people(id) on delete cascade,
  series text not null check (series in ('F1','F2','F3')),
  season integer not null,
  entrant_name text not null,
  car_number integer,
  entry_role text not null default 'race_driver' check (entry_role in ('race_driver','reserve_driver','test_driver')),
  source_key text not null references public.data_sources(source_key),
  verified_on date not null,
  unique(person_id, series, season, entrant_name, entry_role)
);

create table if not exists public.f1_team_staff (
  id bigint generated by default as identity primary key,
  team_id bigint not null references public.f1_team_facts(id) on delete cascade,
  person_id bigint not null references public.people(id) on delete cascade,
  season integer not null,
  role_title text not null,
  source_key text not null references public.data_sources(source_key),
  verified_on date not null,
  unique(team_id, person_id, season, role_title)
);

create table if not exists public.track_facts (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  circuit_name text not null,
  display_name text not null,
  city text,
  country text not null,
  circuit_type text check (circuit_type in ('permanent','street','temporary','semi_permanent')),
  lap_length_km numeric(6,3),
  race_laps integer,
  race_distance_km numeric(7,3),
  first_f1_grand_prix_year integer,
  official_2026_calendar boolean not null default false,
  confirmed_future_event boolean not null default false,
  source_key text not null references public.data_sources(source_key),
  verified_on date not null
);

