alter table public.data_sources enable row level security;
alter table public.f1_team_facts enable row level security;
alter table public.people enable row level security;
alter table public.series_entries enable row level security;
alter table public.f1_team_staff enable row level security;
alter table public.track_facts enable row level security;

-- Abort the migration if a compact seed list is accidentally truncated.
do $$
begin
  if (select count(*) from public.f1_team_facts where verified_on='2026-08-31') <> 11 then
    raise exception 'Fact seed validation failed: expected 11 F1 teams';
  end if;
  if (select count(*) from public.series_entries where series='F1' and season=2026 and entry_role='race_driver') <> 22 then
    raise exception 'Fact seed validation failed: expected 22 F1 race drivers';
  end if;
  if (select count(*) from public.series_entries where series='F2' and season=2026 and entry_role='race_driver') <> 22 then
    raise exception 'Fact seed validation failed: expected 22 F2 race drivers';
  end if;
  if (select count(*) from public.series_entries where series='F3' and season=2026 and entry_role='race_driver') <> 30 then
    raise exception 'Fact seed validation failed: expected 30 F3 race drivers';
  end if;
  if (select count(*) from public.track_facts where official_2026_calendar or confirmed_future_event) <> 24 then
    raise exception 'Fact seed validation failed: expected 24 relevant tracks';
  end if;
end $$;
